#!/usr/bin/env python3
"""
Chocolate Retail Sales Performance Report Generator
Analyzes 2023-2024 sales data and generates comprehensive HTML report.
"""

import pandas as pd
import matplotlib.pyplot as plt
import matplotlib
matplotlib.use('Agg')
import numpy as np
from datetime import datetime
from io import BytesIO
import base64
import json

# Load data
print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv')
df['order_date'] = pd.to_datetime(df['order_date'])
df['year'] = df['order_date'].dt.year
df['month'] = df['order_date'].dt.month
df['quarter'] = df['order_date'].dt.quarter
df['year_month'] = df['order_date'].dt.to_period('M')

# Calculate margin
df['margin'] = (df['profit'] / df['revenue'] * 100).replace([np.inf, -np.inf], 0)

print(f"Data loaded: {len(df):,} records")

# =============================================================================
# HELPER FUNCTIONS
# =============================================================================

def fig_to_base64(fig):
    """Convert matplotlib figure to base64 encoded PNG."""
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

def create_time_series_chart(data, x_col, y_cols, title, xlabel, ylabel, colors=None):
    """Create a line chart for time series data."""
    fig, ax = plt.subplots(figsize=(10, 5))
    if colors is None:
        colors = ['#1e40af', '#6b7280', '#059669', '#d97706']
    for i, col in enumerate(y_cols):
        ax.plot(data[x_col].astype(str), data[col], marker='o', linewidth=2,
                label=col, color=colors[i % len(colors)], markersize=4)
    ax.set_xlabel(xlabel, fontsize=11)
    ax.set_ylabel(ylabel, fontsize=11)
    ax.set_title(title, fontsize=13, fontweight='bold', pad=15)
    ax.legend(loc='upper left')
    ax.grid(True, alpha=0.3)
    plt.xticks(rotation=45, ha='right')
    plt.tight_layout()
    return fig

def create_bar_chart(data, x_col, y_col, title, xlabel, ylabel, color='#1e40af', horizontal=False):
    """Create a bar chart."""
    fig, ax = plt.subplots(figsize=(10, 5))
    if horizontal:
        ax.barh(data[x_col], data[y_col], color=color)
        ax.set_xlabel(xlabel, fontsize=11)
        ax.set_ylabel(ylabel, fontsize=11)
    else:
        ax.bar(data[x_col].astype(str), data[y_col], color=color)
        ax.set_xlabel(xlabel, fontsize=11)
        ax.set_ylabel(ylabel, fontsize=11)
        plt.xticks(rotation=45, ha='right')
    ax.set_title(title, fontsize=13, fontweight='bold', pad=15)
    ax.grid(True, alpha=0.3, axis='y')
    plt.tight_layout()
    return fig

def create_grouped_bar_chart(data, x_col, y_cols, title, xlabel, ylabel, colors=None):
    """Create grouped bar chart."""
    fig, ax = plt.subplots(figsize=(12, 5))
    x = np.arange(len(data[x_col]))
    width = 0.35
    if colors is None:
        colors = ['#1e40af', '#6b7280']
    for i, col in enumerate(y_cols):
        offset = (i - len(y_cols)/2 + 0.5) * width
        ax.bar(x + offset, data[col], width, label=col, color=colors[i])
    ax.set_xlabel(xlabel, fontsize=11)
    ax.set_ylabel(ylabel, fontsize=11)
    ax.set_title(title, fontsize=13, fontweight='bold', pad=15)
    ax.set_xticks(x)
    ax.set_xticklabels(data[x_col].astype(str), rotation=45, ha='right')
    ax.legend()
    ax.grid(True, alpha=0.3, axis='y')
    plt.tight_layout()
    return fig

def create_pie_chart(data, values_col, labels_col, title, colors=None):
    """Create a pie chart."""
    fig, ax = plt.subplots(figsize=(8, 6))
    if colors is None:
        colors = plt.cm.Set3.colors
    wedges, texts, autotexts = ax.pie(data[values_col], labels=data[labels_col],
                                       autopct='%1.1f%%', colors=colors,
                                       pctdistance=0.75)
    for autotext in autotexts:
        autotext.set_fontsize(10)
    ax.set_title(title, fontsize=13, fontweight='bold', pad=15)
    plt.tight_layout()
    return fig

def create_scatter_chart(data, x_col, y_col, title, xlabel, ylabel, color='#1e40af'):
    """Create scatter chart."""
    fig, ax = plt.subplots(figsize=(8, 6))
    ax.scatter(data[x_col], data[y_col], alpha=0.5, color=color)
    ax.set_xlabel(xlabel, fontsize=11)
    ax.set_ylabel(ylabel, fontsize=11)
    ax.set_title(title, fontsize=13, fontweight='bold', pad=15)
    ax.grid(True, alpha=0.3)
    plt.tight_layout()
    return fig

# =============================================================================
# CALCULATE KPIs
# =============================================================================

print("Calculating KPIs...")
total_revenue = df['revenue'].sum()
total_profit = df['profit'].sum()
total_orders = len(df)
avg_profit_margin = (df['profit'].sum() / df['revenue'].sum() * 100)
avg_order_value = df['revenue'].mean()
discount_utilization = (df['discount'] > 0).mean() * 100

# Year-over-year
rev_2023 = df[df['year'] == 2023]['revenue'].sum()
rev_2024 = df[df['year'] == 2024]['revenue'].sum()
yoy_growth = ((rev_2024 - rev_2023) / rev_2023 * 100)

# =============================================================================
# SECTION 1: EXECUTIVE SUMMARY
# =============================================================================

print("Generating Executive Summary...")

# Monthly trends for YoY comparison
monthly_rev = df.groupby(['year', 'month'])['revenue'].sum().reset_index()
monthly_rev_pivot = monthly_rev.pivot(index='month', columns='year', values='revenue')

# Q4 holiday boost analysis
q4_data = df[df['quarter'] == 4].groupby('year')['revenue'].sum()
q4_2023 = q4_data.get(2023, 0)
q4_2024 = q4_data.get(2024, 0)

# Top product category
product_cats = df.groupby('category').agg({'revenue': 'sum', 'profit': 'sum'}).reset_index()
top_cat = product_cats.nlargest(1, 'revenue')['category'].values[0]

# Top store city
store_rev = df.groupby('city')['revenue'].sum().reset_index()
top_city = store_rev.nlargest(1, 'revenue')['city'].values[0]

# =============================================================================
# SECTION 2: SALES TRENDS
# =============================================================================

print("Generating Sales Trends...")

# Monthly revenue
monthly_summary = df.groupby('year_month').agg({
    'revenue': 'sum',
    'profit': 'sum',
    'order_id': 'count'
}).reset_index()
monthly_summary.columns = ['period', 'revenue', 'profit', 'orders']
monthly_summary['period'] = monthly_summary['period'].astype(str)

# Quarterly revenue
quarterly_summary = df.groupby(['year', 'quarter']).agg({
    'revenue': 'sum',
    'profit': 'sum',
    'order_id': 'count'
}).reset_index()
quarterly_summary.columns = ['year', 'quarter', 'revenue', 'profit', 'orders']

# =============================================================================
# SECTION 3: PRODUCT PERFORMANCE
# =============================================================================

print("Generating Product Performance...")

# By category
category_summary = df.groupby('category').agg({
    'revenue': 'sum',
    'profit': 'sum',
    'order_id': 'count'
}).reset_index()
category_summary['avg_margin'] = (category_summary['profit'] / category_summary['revenue'] * 100)
category_summary = category_summary.sort_values('revenue', ascending=False)

# By brand
brand_summary = df.groupby('brand').agg({
    'revenue': 'sum',
    'profit': 'sum',
    'order_id': 'count'
}).reset_index()
brand_summary['avg_margin'] = (brand_summary['profit'] / brand_summary['revenue'] * 100)
brand_summary = brand_summary.sort_values('revenue', ascending=False).head(10)

# By cocoa percent
df['cocoa_bin'] = pd.cut(df['cocoa_percent'], bins=[0, 30, 50, 70, 90, 100], labels=['0-30%', '30-50%', '50-70%', '70-90%', '90-100%'])
cocoa_summary = df.groupby('cocoa_bin').agg({
    'revenue': 'sum',
    'profit': 'sum',
    'order_id': 'count'
}).reset_index()
cocoa_summary['avg_margin'] = (cocoa_summary['profit'] / cocoa_summary['revenue'] * 100)

# =============================================================================
# SECTION 4: STORE ANALYSIS
# =============================================================================

print("Generating Store Analysis...")

# By store type
store_type_summary = df.groupby('store_type').agg({
    'revenue': 'sum',
    'profit': 'sum',
    'order_id': 'count'
}).reset_index()
store_type_summary['avg_order_value'] = store_type_summary['revenue'] / store_type_summary['order_id']
store_type_summary['avg_margin'] = (store_type_summary['profit'] / store_type_summary['revenue'] * 100)
store_type_summary = store_type_summary.sort_values('revenue', ascending=False)

# By country
country_summary = df.groupby('country').agg({
    'revenue': 'sum',
    'profit': 'sum',
    'order_id': 'count'
}).reset_index()
country_summary['avg_order_value'] = country_summary['revenue'] / country_summary['order_id']
country_summary = country_summary.sort_values('revenue', ascending=False)

# Top 10 stores
store_summary = df.groupby('store_id').agg({
    'revenue': 'sum',
    'profit': 'sum',
    'order_id': 'count'
}).reset_index()
store_summary['avg_order_value'] = store_summary['revenue'] / store_summary['order_id']
store_summary['avg_margin'] = (store_summary['profit'] / store_summary['revenue'] * 100)
top_stores = store_summary.nlargest(10, 'revenue')

# Bottom 5 stores
bottom_stores = store_summary.nsmallest(5, 'revenue')

# =============================================================================
# SECTION 5: DISCOUNT IMPACT
# =============================================================================

print("Generating Discount Impact Analysis...")

# Discount distribution
df['discount_bin'] = pd.cut(df['discount'], bins=[-0.01, 0, 0.05, 0.10, 0.15, 0.20, 1.0],
                            labels=['0%', '1-5%', '6-10%', '11-15%', '16-20%', '>20%'])
discount_summary = df.groupby('discount_bin').agg({
    'revenue': ['sum', 'mean'],
    'profit': ['sum', 'mean'],
    'order_id': 'count',
    'quantity': 'mean'
}).reset_index()
discount_summary.columns = ['discount_tier', 'total_revenue', 'avg_revenue', 'total_profit',
                              'avg_profit', 'order_count', 'avg_quantity']
discount_summary['avg_margin'] = (discount_summary['total_profit'] / discount_summary['total_revenue'] * 100)

# Non-discounted vs discounted comparison
no_discount = df[df['discount'] == 0]
with_discount = df[df['discount'] > 0]
disc_stats = {
    'no_discount': {
        'count': len(no_discount),
        'revenue': no_discount['revenue'].sum(),
