def fig_to_base64(fig):
    """Convert matplotlib figure to base64 encoded PNG."""
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

def create_time_series_chart(data, x_col, y_cols, title, xlabel, ylabel, colors=None):
    """Create a line chart for time series data."""
    fig, ax = plt.subplots(figsize=(10, 5))
    if colors is None:
        colors = ['#1e40af', '#6b7280', '#059669', '#d97706']
    for i, col in enumerate(y_cols):
        ax.plot(data[x_col].astype(str), data[col], marker='o', linewidth=2,
                label=col, color=colors[i % len(colors)], markersize=4)
    ax.set_xlabel(xlabel, fontsize=11)
    ax.set_ylabel(ylabel, fontsize=11)
    ax.set_title(title, fontsize=13, fontweight='bold', pad=15)
    ax.legend(loc='upper left')
    ax.grid(True, alpha=0.3)
    plt.xticks(rotation=45, ha='right')
    plt.tight_layout()
    return fig

def create_bar_chart(data, x_col, y_col, title, xlabel, ylabel, color='#1e40af', horizontal=False):
    """Create a bar chart."""
    fig, ax = plt.subplots(figsize=(10, 5))
    if horizontal:
        bars = ax.barh(data[x_col].astype(str), data[y_col], color=color)
        ax.set_xlabel(xlabel, fontsize=11)
        ax.set_ylabel(ylabel, fontsize=11)
    else:
        bars = ax.bar(data[x_col].astype(str), data[y_col], color=color)
        ax.set_xlabel(xlabel, fontsize=11)
        ax.set_ylabel(ylabel, fontsize=11)
        plt.xticks(rotation=45, ha='right')
    ax.set_title(title, fontsize=13, fontweight='bold', pad=15)
    ax.grid(True, alpha=0.3, axis='y')
    plt.tight_layout()
    return fig

def create_grouped_bar_chart(data, x_col, y_cols, title, xlabel, ylabel, colors=None):
    """Create grouped bar chart."""
    fig, ax = plt.subplots(figsize=(12, 5))
    x = np.arange(len(data[x_col]))
    width = 0.35
    if colors is None:
        colors = ['#1e40af', '#6b7280']
    for i, col in enumerate(y_cols):
        offset = (i - len(y_cols)/2 + 0.5) * width
        ax.bar(x + offset, data[col], width, label=col, color=colors[i])
    ax.set_xlabel(xlabel, fontsize=11)
    ax.set_ylabel(ylabel, fontsize=11)
    ax.set_title(title, fontsize=13, fontweight='bold', pad=15)
    ax.set_xticks(x)
