    wedges, texts, autotexts = ax.pie(data[values_col], labels=data[labels_col],
                                       autopct='%1.1f%%', colors=colors,
                                       pctdistance=0.75)
    for autotext in autotexts:
        autotext.set_fontsize(10)
    ax.set_title(title, fontsize=13, fontweight='bold', pad=15)
